import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-math-stats-l4-001', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Information Theory', question: 'What is the relationship between KL divergence and cross-entropy loss used in classification?', options: ['Cross-entropy H(p,q) = H(p) + KL(p||q), where H(p) is the entropy of the true distribution and KL(p||q) is the KL divergence. Since H(p) is constant for fixed labels, minimizing cross-entropy is equivalent to minimizing KL divergence between the true label distribution and the model\'s predicted distribution. This connects information theory to the most common classification loss function', 'KL divergence is symmetric while cross-entropy is not', 'KL divergence and cross-entropy are unrelated', 'Cross-entropy is always larger than KL divergence by a factor of 2'], correctAnswer: 0, explanation: 'For one-hot labels p (entropy H(p)=0), CE = KL exactly. For soft labels (label smoothing), H(p) > 0 so CE = H(p) + KL(p||q). Minimizing CE with respect to q minimizes KL regardless, since H(p) doesn\'t depend on q. KL divergence properties: (1) non-negative (Gibbs inequality), (2) zero iff p=q, (3) NOT symmetric: KL(p||q) ≠ KL(q||p). Forward KL: KL(p||q) is mean-seeking (q covers all modes of p). Reverse KL: KL(q||p) is mode-seeking (q concentrates on one mode of p). This matters for variational inference where the direction determines behavior.', tags: ['kl-divergence', 'cross-entropy', 'information-theory', 'loss-function'] },
  { id: 'ai-engineer-math-stats-l4-002', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'What is the connection between SVD (Singular Value Decomposition) and PCA, and why is truncated SVD used for dimensionality reduction?', options: ['PCA requires the full eigendecomposition of the data matrix', 'Truncated SVD always preserves 100% of the information', 'SVD and PCA are completely different algorithms', 'PCA finds the directions of maximum variance in data. These directions are the right singular vectors of the mean-centered data matrix, and the singular values encode the variance along each direction. Truncated SVD keeps only the top-k singular values/vectors, providing the best rank-k approximation in Frobenius norm (Eckart-Young theorem). This is both the optimal dimensionality reduction and the foundation for techniques like LSA in NLP'], correctAnswer: 3, explanation: 'Data matrix X (centered): X = UΣV^T. Principal components: columns of V (right singular vectors). Explained variance: σ_i² / Σσ_j². Truncated SVD: keep top-k singular values → X_k = U_k Σ_k V_k^T is the best rank-k approximation minimizing ||X - X_k||_F (Eckart-Young). Applications in ML: (1) PCA for feature reduction, (2) LSA = truncated SVD on TF-IDF matrix for topic modeling, (3) LoRA uses low-rank approximation of weight updates. Computational: full SVD is O(mn·min(m,n)), but randomized SVD (sklearn\'s default) approximates top-k in O(mn·k), making it practical for large datasets.', tags: ['svd', 'pca', 'dimensionality-reduction', 'eckart-young'] },
  { id: 'ai-engineer-math-stats-l4-003', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the reparameterization trick in VAEs and why is it necessary for gradient-based optimization?', options: ['Sampling z ~ N(μ, σ²) is a stochastic operation that blocks gradient flow (cannot backpropagate through random sampling). The reparameterization trick rewrites z = μ + σ·ε where ε ~ N(0,1), making z a deterministic function of μ and σ with the randomness in ε (which has no learnable parameters). This enables standard backpropagation through the sampling operation to update μ and σ via gradient descent', 'This trick only works with Gaussian distributions', 'The reparameterization trick is a regularization method', 'The reparameterization trick eliminates the need for sampling'], correctAnswer: 0, explanation: 'Without reparameterization: z ~ q(z|x) = N(μ(x), σ²(x)). Gradient ∇_θ E_q[f(z)] requires differentiating through the sampling, which is not straightforward. With reparameterization: z = μ(x) + σ(x) · ε, ε ~ N(0,1). Now ∇_θ E_ε[f(μ + σ·ε)] = E_ε[∇_θ f(μ + σ·ε)], which is estimatable via standard backprop. This works for any location-scale distribution family (Gaussian, Logistic, etc.). For discrete distributions: Gumbel-softmax trick provides a continuous relaxation analogous to reparameterization. This is fundamental to VAE training and any variational inference method using neural networks.', tags: ['reparameterization', 'vae', 'gradient-estimation', 'variational-inference'] },
  { id: 'ai-engineer-math-stats-l4-004', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is the Adam optimizer doing differently from SGD with momentum, and what is the role of the bias correction terms?', options: ['Adam always converges faster than SGD', 'Adam maintains both first moment (mean of gradients, like momentum) and second moment (mean of squared gradients, like RMSProp) estimates. The update divides the momentum by the square root of the second moment, providing per-parameter adaptive learning rates. Bias correction (dividing by 1-β^t) compensates for the initialization bias toward zero in the first few steps, ensuring accurate moment estimates from the start of training', 'Adam is identical to SGD with momentum', 'Bias correction has no practical effect on training'], correctAnswer: 1, explanation: 'Adam update: m_t = β₁·m_{t-1} + (1-β₁)·g_t (first moment), v_t = β₂·v_{t-1} + (1-β₂)·g_t² (second moment). Without correction: m_t is biased toward 0 at the start (initialized to 0, β₁=0.9 means m₁ = 0.1·g₁). Correction: m̂_t = m_t/(1-β₁^t), v̂_t = v_t/(1-β₂^t). At t=1: m̂₁ = g₁ (unbiased). Update: θ -= lr · m̂_t / (√v̂_t + ε). Per-parameter LR: parameters with large gradient variance get smaller updates (√v̂_t is large), stabilizing training. SGD + momentum lacks the adaptive LR. Practical: Adam converges faster early but SGD often finds better minima with proper scheduling (warmup + cosine decay).', tags: ['adam', 'sgd', 'bias-correction', 'adaptive-lr'] },
  { id: 'ai-engineer-math-stats-l4-005', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Bayesian', question: 'What is the Evidence Lower Bound (ELBO) and why is it used instead of directly maximizing the marginal likelihood?', options: ['The ELBO is always equal to the marginal likelihood', 'The marginal likelihood p(x) = ∫p(x|z)p(z)dz is intractable for complex models because the integral over latent variables z has no closed form. The ELBO provides a tractable lower bound: ELBO = E_q[log p(x|z)] - KL(q(z|x)||p(z)) ≤ log p(x). Maximizing the ELBO simultaneously: (1) maximizes reconstruction quality (first term), (2) regularizes the latent space (second term), and (3) tightens the bound on the true marginal likelihood', 'The ELBO is an upper bound on the marginal likelihood', 'The ELBO can only be used with Gaussian distributions'], correctAnswer: 1, explanation: 'Derivation: log p(x) = ELBO + KL(q(z|x)||p(z|x)). Since KL ≥ 0, ELBO ≤ log p(x). The gap is KL between the approximate posterior q and the true posterior p(z|x). Better q → smaller gap → tighter bound. ELBO = E_q[log p(x|z)] - KL(q(z|x)||p(z)): first term = reconstruction (decode z → x), second term = regularization (keep q close to prior p(z)). In VAEs: q is the encoder, p(x|z) is the decoder, p(z) = N(0,I). The β-VAE weights the KL term by β to control the reconstruction-regularization trade-off. IWAE (importance-weighted AE) uses multiple samples to get a tighter bound than the standard single-sample ELBO.', tags: ['elbo', 'variational-inference', 'marginal-likelihood', 'vae'] },
  { id: 'ai-engineer-math-stats-l4-006', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Kernel Methods', question: 'What is the kernel trick and why does it enable SVMs to handle non-linearly separable data?', options: ['The kernel trick computes dot products in a high-dimensional feature space without explicitly computing the feature mapping: K(x,y) = φ(x)·φ(y). For example, the RBF kernel K(x,y) = exp(-||x-y||²/2σ²) implicitly maps to an infinite-dimensional space where any dataset is linearly separable. SVMs only need dot products between data points (in the dual formulation), so the kernel trick avoids the computational cost of explicit high-dimensional mapping', 'The kernel trick projects data to a lower-dimensional space', 'Kernel methods only work with polynomial features', 'The kernel trick reduces computational cost by using fewer features'], correctAnswer: 0, explanation: 'SVM dual: maximize Σα_i - ½ΣΣα_iα_jy_iy_j·K(x_i,x_j). Only dot products K(x_i,x_j) appear — never individual feature vectors. Polynomial kernel: K(x,y) = (x·y + c)^d corresponds to all polynomial features up to degree d. RBF kernel: K(x,y) = exp(-γ||x-y||²) corresponds to infinite-dimensional feature space (Taylor expansion of exp gives infinite terms). Mercer\'s theorem: any positive semi-definite function is a valid kernel (corresponds to some feature mapping). Computational cost: compute N×N kernel matrix O(N²d) instead of mapping to potentially infinite dimensions. Limitation: N×N kernel matrix is O(N²) memory, limiting SVMs to ~100K examples. Nyström approximation and random Fourier features approximate kernels to scale further.', tags: ['kernel-trick', 'svm', 'rbf', 'feature-mapping'] },
  { id: 'ai-engineer-math-stats-l4-007', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Statistics', question: 'What is the bootstrap method and why is it useful for estimating confidence intervals of ML metrics?', options: ['Bootstrap repeatedly samples with replacement from the observed data to create B pseudo-datasets, computes the statistic of interest on each, and uses the distribution of these B statistics to estimate confidence intervals. For ML: it provides confidence intervals for accuracy, F1, AUC without distributional assumptions. This is critical because ML metrics often have unknown distributions, especially for small test sets or metrics computed on specific slices', 'Bootstrap requires at least 10,000 data points to work', 'Bootstrap requires knowing the population distribution', 'Bootstrap always produces wider confidence intervals than parametric methods'], correctAnswer: 0, explanation: 'Bootstrap procedure: (1) from test set of N examples, sample N with replacement (some examples appear multiple times, some not at all), (2) compute metric (accuracy) on this bootstrap sample, (3) repeat B=1000 times → distribution of metric values, (4) 95% CI = [2.5th percentile, 97.5th percentile] of the B values. For ML: particularly valuable for: (a) small test sets where CLT-based intervals are unreliable, (b) complex metrics (F1, AUC) where variance formulas are complicated, (c) comparing two models (bootstrap difference in metrics). BCa (bias-corrected and accelerated) bootstrap improves coverage for skewed statistics. Paired bootstrap: sample the same indices for both models to compute CI of the performance difference, reducing variance.', tags: ['bootstrap', 'confidence-intervals', 'nonparametric', 'statistical-inference'] },
  { id: 'ai-engineer-math-stats-l4-008', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Information Theory', question: 'What is mutual information and how is it used for feature selection in ML?', options: ['Mutual information can be negative', 'Mutual information only measures linear relationships', 'Mutual information I(X;Y) = H(X) - H(X|Y) measures the reduction in uncertainty about X when Y is known. Unlike correlation (which only captures linear relationships), MI captures any statistical dependency. For feature selection: rank features by MI with the target variable — features with high MI are most informative. MI is non-negative, zero iff X and Y are independent, and does not assume any functional form of the relationship', 'MI is identical to Pearson correlation for all distributions'], correctAnswer: 2, explanation: 'MI properties: (1) I(X;Y) ≥ 0, with equality iff X⊥Y, (2) I(X;Y) = I(Y;X) (symmetric), (3) invariant under invertible transformations of X or Y. For continuous features: I(X;Y) = ∫∫ p(x,y) log(p(x,y)/(p(x)p(y))) dx dy. Estimation: k-nearest-neighbor estimators (sklearn.feature_selection.mutual_info_classif uses Kraskov et al. 2004). Feature selection: compute MI between each feature and target → select top-k features. Advantages over correlation: detects non-linear dependencies (e.g., Y = X² has zero correlation but high MI). Limitation: MI between feature and target doesn\'t account for redundancy between features — mRMR (maximum relevance minimum redundancy) addresses this by penalizing features that are redundant with already-selected features.', tags: ['mutual-information', 'feature-selection', 'entropy', 'dependency'] },
  { id: 'ai-engineer-math-stats-l4-009', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'Why is the condition number of a matrix important for numerical stability in ML optimization?', options: ['Condition number is only relevant for solving linear systems', 'The condition number is always 1 for square matrices', 'Low condition numbers indicate numerical instability', 'The condition number κ(A) = σ_max/σ_min (ratio of largest to smallest singular value) measures how sensitive the solution of Ax=b is to perturbations in A or b. High condition number means: (1) small gradient changes cause large parameter updates, (2) floating-point errors are amplified, (3) optimization landscapes have elongated valleys causing slow convergence. In ML: the Hessian\'s condition number determines convergence speed — preconditioning techniques (Adam, natural gradient) effectively reduce it'], correctAnswer: 3, explanation: 'For gradient descent on quadratic loss: convergence rate ∝ (κ-1)/(κ+1). If κ=100: rate ≈ 0.98 (slow). If κ=2: rate ≈ 0.33 (fast). The condition number of the Hessian H of the loss function determines how "elongated" the loss landscape is. High κ: gradients zigzag along narrow valleys. Solutions: (1) feature normalization (reduces κ of the data covariance matrix), (2) Adam optimizer (divides by √(second moment), approximating diagonal preconditioning), (3) natural gradient (preconditions by Fisher information matrix), (4) weight initialization (Kaiming/Xavier keep activation variances stable, indirectly controlling κ). Ill-conditioned problems: matrix inversion, least-squares with collinear features — regularization (Ridge) adds λI, improving κ to (σ_max+λ)/(σ_min+λ).', tags: ['condition-number', 'numerical-stability', 'preconditioning', 'convergence'] },
  { id: 'ai-engineer-math-stats-l4-010', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the difference between frequentist and Bayesian approaches to uncertainty in ML predictions?', options: ['Bayesian methods always require MCMC sampling', 'Frequentist: parameters are fixed unknowns, uncertainty comes from data randomness. Confidence intervals describe repeated sampling behavior ("if we repeated the experiment, 95% of intervals would contain the true value"). Bayesian: parameters have distributions encoding beliefs, updated via Bayes\' theorem. Credible intervals describe posterior probability ("95% probability the parameter is in this range"). For ML: Bayesian approaches provide principled uncertainty estimates but are computationally expensive; frequentist approaches are efficient but limited in their uncertainty characterization', 'Frequentist and Bayesian approaches give identical results', 'Frequentist methods provide probability statements about parameters'], correctAnswer: 1, explanation: 'Frequentist ML: MLE/MAP point estimates, confidence intervals via bootstrap or asymptotic theory. Quick but: (1) no uncertainty over model parameters, (2) prediction intervals don\'t capture model uncertainty, (3) can\'t incorporate prior knowledge formally. Bayesian ML: posterior p(θ|D) ∝ p(D|θ)p(θ), predictions integrate over parameter uncertainty: p(y|x,D) = ∫p(y|x,θ)p(θ|D)dθ. Naturally calibrated uncertainty. But: exact posterior is intractable for large models, approximations (variational inference, Laplace, MC Dropout, ensembles) are needed. Practical compromise: deep ensembles (train 5 models, use prediction variance as uncertainty) — frequentist training with Bayesian-like uncertainty. BNNs with last-layer Laplace approximation provide efficient posterior estimates.', tags: ['frequentist', 'bayesian', 'uncertainty', 'credible-intervals'] },
  { id: 'ai-engineer-math-stats-l4-011', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is the relationship between batch size, learning rate, and gradient noise in SGD?', options: ['Batch size has no effect on the optimal learning rate', 'Gradient noise is independent of batch size', 'Larger batch sizes always require smaller learning rates', 'Gradient noise ∝ σ/√B where σ is per-sample gradient variance and B is batch size. Doubling batch size halves the noise, which is equivalent to halving the effective learning rate. The "linear scaling rule": when increasing batch size by k, increase learning rate by k to maintain the same noise-to-signal ratio. This breaks down at very large batch sizes (past the critical batch size) where the gradient is already a good estimate and more noise reduction doesn\'t help convergence'], correctAnswer: 3, explanation: 'SGD gradient: g_B = (1/B)Σ∇L_i. Variance: Var(g_B) = σ²/B. SGD update: θ -= lr · g_B. Effective noise: lr · σ/√B. If B → 2B: noise decreases by √2. To compensate: lr → 2·lr. This is the Goyal et al. (2017) linear scaling rule (used to train ImageNet with batch 8192). Warm-up: at training start, gradients have high variance → large LR with large batch causes instability. Gradually increase LR over 5-10 epochs. Critical batch size B_crit ≈ B_noise = tr(Σ)/||G||²: below B_crit, doubling B effectively doubles throughput; above B_crit, diminishing returns. For LLMs: B_crit can be millions of tokens, motivating large batch training.', tags: ['batch-size', 'learning-rate', 'gradient-noise', 'linear-scaling'] },
  { id: 'ai-engineer-math-stats-l4-012', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Attention Math', question: 'What is the mathematical formulation of scaled dot-product attention and why is the scaling factor √d_k necessary?', options: ['The scaling factor is purely aesthetic', 'Scaling by √d_k increases the attention sharpness', 'Attention(Q,K,V) = softmax(QK^T/√d_k)V. Without scaling, the dot products QK^T grow in magnitude proportionally to d_k (each dot product sums d_k terms). Large magnitude inputs to softmax push it into regions with vanishingly small gradients (near-one-hot outputs). Dividing by √d_k normalizes the variance of the dot products to approximately 1 regardless of d_k, keeping softmax in a well-behaved gradient regime', 'The scaling factor should be d_k, not √d_k'], correctAnswer: 2, explanation: 'If q, k are random vectors with zero mean and unit variance per component: E[q·k] = 0, Var(q·k) = d_k (each component product has variance 1, sum of d_k independent terms). For d_k=64: Var = 64, std = 8. Dot products can be ~±16, making softmax near-one-hot (exp(16)/exp(-16) ≈ e^32). After scaling: Var(q·k/√d_k) = 1, keeping softmax well-behaved. This is critical for training stability: without scaling, gradients through softmax are nearly zero for non-maximum elements, making most of the K×V computation wasted. Flash Attention handles this scaling internally while computing attention in a memory-efficient tiled fashion.', tags: ['attention', 'scaling', 'softmax', 'gradient-stability'] },
  { id: 'ai-engineer-math-stats-l4-013', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Statistics', question: 'What is the multiple testing problem in ML evaluation and how does the Bonferroni correction address it?', options: ['Testing multiple metrics has no statistical implications', 'Testing more metrics always increases statistical power', 'When evaluating K metrics simultaneously (accuracy, precision, recall, F1, AUC...), each at significance level α=0.05, the probability of at least one false positive is 1-(1-α)^K ≈ 0.23 for K=5. The Bonferroni correction tests each at α/K (0.01 for K=5), controlling the family-wise error rate at α. For ML: comparing models across many metrics or data slices inflates false discovery risk. Benjamini-Hochberg FDR correction is less conservative and often more practical for exploratory analysis', 'Bonferroni correction is only used in medical research'], correctAnswer: 2, explanation: 'Scenario: compare model A vs B on 20 data slices at α=0.05 each. Expected false positives: 0.05 × 20 = 1 slice will appear "significantly different" by chance. Bonferroni: test each slice at α/20 = 0.0025. This controls family-wise error rate (probability of ANY false positive ≤ 0.05). Downside: very conservative (high false negative rate). Benjamini-Hochberg: control FDR (expected proportion of false positives among discoveries) at 0.05. Sort p-values: p(1) ≤ p(2) ≤ ... ≤ p(K). Reject all p(i) ≤ i·α/K. Less conservative, more discoveries. For ML practice: use BH correction when evaluating model across many slices, report both uncorrected and corrected significance levels, and always pre-register your primary metric to avoid post-hoc cherry-picking.', tags: ['multiple-testing', 'bonferroni', 'fdr', 'statistical-significance'] },
  { id: 'ai-engineer-math-stats-l4-014', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'What is the relationship between the eigenvalues of the Hessian matrix and the loss landscape geometry?', options: ['Eigenvalues of the Hessian are unrelated to the loss landscape', 'All eigenvalues of the Hessian are always positive for neural networks', 'The Hessian is always a diagonal matrix for deep learning', 'The Hessian eigenvalues describe the curvature of the loss surface in each direction: positive eigenvalues indicate a bowl (convex direction), negative eigenvalues indicate a saddle (concave direction), zero eigenvalues indicate flat directions. The ratio λ_max/λ_min determines the condition number and optimization difficulty. Deep networks have loss landscapes with many near-zero eigenvalues (flat directions) and a few large ones, making optimization challenging and motivating adaptive methods like Adam'], correctAnswer: 3, explanation: 'The Hessian H = ∇²L encodes second-order loss information. Eigenvalue λ_i with eigenvector v_i: moving along v_i, the loss curves with curvature λ_i. Positive: valley (good). Negative: ridge (saddle point). Zero: flat (plateau). For deep networks: (1) most eigenvalues are near zero (the loss is approximately flat in most directions), (2) a few large positive eigenvalues (sharp directions), (3) saddle points are more common than local minima in high dimensions (a random critical point has positive and negative eigenvalues). This explains why SGD works: noise helps escape saddle points (along negative curvature directions). Sharpness-Aware Minimization (SAM) explicitly seeks minima with smaller max eigenvalue for better generalization.', tags: ['hessian', 'eigenvalues', 'loss-landscape', 'curvature'] },
  { id: 'ai-engineer-math-stats-l4-015', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the Gumbel-softmax trick for differentiable sampling from categorical distributions?', options: ['The Gumbel-softmax trick only works with binary variables', 'Gumbel-softmax produces exact one-hot samples', 'Temperature has no effect on the Gumbel-softmax output', 'Gumbel-softmax relaxes discrete sampling into a differentiable operation: add Gumbel noise to log-probabilities, then apply softmax with a temperature parameter. At low temperature, the output approaches one-hot (like argmax); at high temperature, it approaches uniform. This enables gradient-based optimization of models with discrete latent variables (e.g., discrete VAEs, hard attention) by providing a continuous relaxation that converges to the true discrete distribution as temperature approaches zero'], correctAnswer: 3, explanation: 'Problem: sampling z = one_hot(argmax(log_probs + Gumbel_noise)) is non-differentiable (argmax has zero gradient everywhere). Gumbel-softmax: replace argmax with softmax/τ: y_i = exp((log_π_i + g_i)/τ) / Σ_j exp((log_π_j + g_j)/τ), where g_i ~ Gumbel(0,1) = -log(-log(U)), U ~ Uniform(0,1). At τ→0: y → one_hot (exact but non-differentiable). At τ=1: y is smooth (differentiable but approximate). Straight-through estimator: use argmax in forward pass, Gumbel-softmax gradient in backward pass. Applications: VQ-VAE, discrete token selection, hard attention, and any model requiring differentiable discrete choices.', tags: ['gumbel-softmax', 'discrete-sampling', 'temperature', 'differentiable'] },
  { id: 'ai-engineer-math-stats-l4-016', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is the saddle point problem in high-dimensional optimization and why is it more concerning than local minima?', options: ['In high-dimensional spaces (millions of parameters), critical points where the gradient is zero are overwhelmingly more likely to be saddle points than local minima. A random critical point of an N-dimensional function has roughly half positive and half negative Hessian eigenvalues (saddle), not all positive (local minimum). The probability of a local minimum decreases exponentially with dimension. SGD with momentum or noise naturally escapes saddle points by following negative curvature directions', 'Local minima are the primary optimization challenge in deep learning', 'Saddle points are the same as local minima', 'Saddle points only exist in 2D optimization problems'], correctAnswer: 0, explanation: 'Random matrix theory: for a random function in N dimensions, the probability that all N Hessian eigenvalues are positive (local min) at a critical point is ~(1/2)^N — exponentially rare for large N. Most critical points are saddle points with a mix of positive and negative curvature. Near a saddle point: gradient is small (training appears stuck), but the loss can decrease by moving along negative curvature directions. SGD noise naturally provides movement along all directions, including negative curvature escaping saddle points. Gradient descent (without noise) can get stuck at saddle points for exponentially long time. This is why: (1) SGD > GD for deep learning, (2) batch noise is beneficial, (3) learning rate warmup helps explore early.', tags: ['saddle-points', 'high-dimensional', 'optimization', 'loss-landscape'] },
  { id: 'ai-engineer-math-stats-l4-017', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Bayesian', question: 'What is the Laplace approximation for posterior inference in neural networks?', options: ['The Hessian computation is trivial for large neural networks', 'The Laplace approximation fits a Gaussian to the posterior centered at the MAP estimate with covariance equal to the inverse Hessian of the negative log-posterior: q(θ) = N(θ_MAP, H⁻¹). For neural networks: it provides uncertainty estimates with minimal overhead — train normally (find MAP), then compute or approximate the Hessian at the solution. Last-layer Laplace only applies this to the final layer, making the Hessian tractable while capturing meaningful predictive uncertainty', 'The Laplace approximation provides exact posterior inference', 'Laplace approximation uses a uniform distribution to approximate the posterior'], correctAnswer: 1, explanation: 'Laplace approximation steps: (1) Find θ_MAP via standard training (SGD/Adam). (2) Compute H = ∇²_θ L(θ_MAP) (Hessian of loss at MAP). (3) Approximate posterior: p(θ|D) ≈ N(θ_MAP, H⁻¹). Prediction: p(y|x*) = ∫p(y|x*,θ)N(θ|θ_MAP, H⁻¹)dθ, linearize to get Gaussian predictive distribution. Full Hessian for a network with P params: P×P matrix (P=100M → 10^16 entries). Approximations: (1) diagonal Hessian (independent parameters), (2) KFAC (Kronecker-factored approximation), (3) last-layer Laplace (only P_last params, e.g., 1000×10 = 10K). Daxberger et al. (2021) showed last-layer Laplace with KFAC provides well-calibrated uncertainty with negligible computational overhead beyond standard training.', tags: ['laplace-approximation', 'posterior-inference', 'hessian', 'uncertainty'] },
  { id: 'ai-engineer-math-stats-l4-018', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the bias-variance trade-off and how does it manifest differently in deep learning?', options: ['Only variance matters in deep learning, bias is always zero', 'Deep learning has eliminated the bias-variance trade-off', 'Bias and variance are always equal for neural networks', 'Classical bias-variance: model complexity increases → bias decreases, variance increases → U-shaped test error. In deep learning: the "double descent" phenomenon shows test error decreasing again past the interpolation threshold (where training error hits zero). Modern heavily over-parameterized networks can have both low bias and low variance, challenging the classical U-shaped curve. This is partly explained by implicit regularization from SGD and the structure of neural network function spaces'], correctAnswer: 3, explanation: 'Classical: E[(y - f̂(x))²] = Bias²(f̂) + Var(f̂) + σ². Increase model complexity: Bias ↓, Var ↑ → optimal at the crossing point. Double descent (Belkin et al. 2019): as model capacity increases past interpolation (model has more parameters than training examples), test error first increases then decreases again. Heavily over-parameterized models (deep networks with 10x more parameters than data) can generalize well. Explanations: (1) SGD implicitly regularizes by finding low-complexity solutions (minimum norm, flat minima), (2) the function space accessible to gradient descent from random init is much smaller than the full parameter space, (3) label noise causes the first peak, while the model eventually "averages out" the noise. This explains why large LLMs generalize despite massive over-parameterization.', tags: ['bias-variance', 'double-descent', 'over-parameterization', 'generalization'] },
  { id: 'ai-engineer-math-stats-l4-019', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Information Theory', question: 'What is the connection between maximum entropy principle and the design of prior distributions?', options: ['Maximum entropy distributions always have zero variance', 'Maximum entropy has no application to prior design', 'The maximum entropy principle states: among all distributions satisfying known constraints, the one with maximum entropy makes the fewest additional assumptions. For ML: if you know the mean and variance, the maximum entropy distribution is Gaussian. If you know the support is [0,∞) and the mean, it\'s exponential. This principle provides a principled way to choose prior distributions in Bayesian ML when only partial information about the distribution is available', 'The uniform distribution never has maximum entropy'], correctAnswer: 2, explanation: 'Maximum entropy examples: Constraint: support {1,...,K} → MaxEnt: uniform (Categorical(1/K)). Constraint: support R, known mean μ and variance σ² → MaxEnt: N(μ, σ²). Constraint: support [0,∞), known mean λ → MaxEnt: Exponential(1/λ). Constraint: support R⁺, known E[log X] and E[X] → MaxEnt: Gamma. Application in ML: (1) Choose priors for Bayesian NN weights: if we only know weights should be centered at 0 with some variance → N(0, σ²) is the principled choice. (2) Output distributions: softmax outputs are maximum entropy for given expected log-probabilities. (3) Feature engineering: if a feature should be in [0,1] with known mean p → Beta distribution is maximum entropy. This connects information theory to Bayesian inference: we should not assume more than the data tells us.', tags: ['maximum-entropy', 'prior-design', 'bayesian', 'information-theory'] },
  { id: 'ai-engineer-math-stats-l4-020', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'How does low-rank matrix factorization relate to LoRA and other parameter-efficient methods?', options: ['LoRA requires the weight matrices to be square', 'Low-rank factorization is unrelated to LoRA', 'Low-rank approximation always loses critical information', 'LoRA constrains weight updates to be low-rank: ΔW = BA where B∈R^{d×r}, A∈R^{r×d}, r≪d. This assumes the weight update during fine-tuning lies in a low-rank subspace. The intuition: fine-tuning changes weights subtly, and these changes are correlated across neurons (low intrinsic dimensionality). Aghajanyan et al. (2021) showed fine-tuning operates in a low intrinsic dimension — a 175B parameter model can be effectively fine-tuned in a subspace of dimension ~200-1000'], correctAnswer: 3, explanation: 'Full fine-tuning: update W ∈ R^{d×d} → d² parameters. LoRA: W\' = W + BA, B∈R^{d×r}, A∈R^{r×d} → 2dr parameters (for r=16, d=4096: 131K vs 16.7M parameters, 127x reduction). Why low rank works: the update ΔW = W_finetuned - W_pretrained has low effective rank — most singular values are near zero. Aghajanyan et al. showed that projecting fine-tuning updates to random low-dimensional subspaces of dimension ~200 recovers 90% of full fine-tuning quality for a 175B model. This is the "intrinsic dimensionality" of the fine-tuning problem. Related methods: adapter layers (bottleneck architecture), prefix tuning (low-rank in the KV space), and IA³ (learned scaling vectors = rank-1 updates).', tags: ['low-rank', 'lora', 'matrix-factorization', 'intrinsic-dimensionality'] },
  { id: 'ai-engineer-math-stats-l4-021', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Statistics', question: 'What is the Simpson\'s paradox and how can it affect ML model evaluation?', options: ['Simpson\'s paradox only occurs in medical studies', 'Simpson\'s paradox occurs when a trend that appears in several groups reverses when the groups are combined. In ML evaluation: model A may outperform model B on every individual demographic group, yet model B outperforms A overall. This happens when group sizes are unbalanced and group difficulty varies. It reveals that aggregate metrics can be misleading and slice-based evaluation is essential for understanding true model performance', 'Simpson\'s paradox cannot occur with ML metrics', 'Larger datasets always prevent Simpson\'s paradox'], correctAnswer: 1, explanation: 'Example: Model A accuracy: Group 1 (900 samples): 85%, Group 2 (100 samples): 90%. Overall: 85.5%. Model B accuracy: Group 1 (100 samples): 80%, Group 2 (900 samples): 85%. Overall: 84.5%. Model A wins overall (85.5% vs 84.5%). But Model B wins in Group 1 (80% vs ?, data skew) and Group 2 (85% vs 90% - wait, Model A wins here). The paradox arises from confounding: groups have different base rates and models are evaluated on different group proportions. For ML: (1) always evaluate per-group performance, not just overall, (2) stratified evaluation reports, (3) caution when comparing models tested on different data distributions. This is why slice-based evaluation (Slice Finder, What-If Tool) is essential.', tags: ['simpsons-paradox', 'evaluation', 'confounding', 'slice-analysis'] },
  { id: 'ai-engineer-math-stats-l4-022', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is the Jacobian matrix and how is it related to backpropagation in deep learning?', options: ['The Jacobian is only used in physics, not ML', 'The Jacobian J of a function f: R^n → R^m is the m×n matrix of partial derivatives J_{ij} = ∂f_i/∂x_j. Backpropagation computes the chain rule as a product of Jacobians: ∂L/∂x = (∂L/∂y)·J, where J is the Jacobian of the layer transforming x→y. In practice, backprop never forms the full Jacobian — it computes the vector-Jacobian product (VJP) directly, which is O(n) instead of O(mn) for the full Jacobian', 'Backpropagation requires computing the full Jacobian at every layer', 'The Jacobian is always a square matrix'], correctAnswer: 1, explanation: 'For a layer y = f(x), x∈R^n, y∈R^m: Jacobian J ∈ R^{m×n}. Chain rule: if L is scalar, ∂L/∂x = (∂L/∂y)^T · J = J^T · (∂L/∂y). This is a VJP (vector-Jacobian product): input is a vector (∂L/∂y ∈ R^m), output is a vector (∂L/∂x ∈ R^n). Cost: O(mn) — same as one forward pass through the layer. Building the full Jacobian would cost O(m·mn) = O(m²n). Reverse mode autodiff (backprop): computes one VJP per layer, propagating from output to input. Forward mode autodiff: computes JVP (Jacobian-vector product), useful when n < m. For neural networks (n is usually much larger than 1): reverse mode is efficient. JAX makes both modes explicit with jax.vjp and jax.jvp.', tags: ['jacobian', 'backpropagation', 'vjp', 'chain-rule'] },
  { id: 'ai-engineer-math-stats-l4-023', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the score function (∇ log p(x)) and why is it central to diffusion models?', options: ['The score function is a metric for model evaluation', 'The score function s(x) = ∇_x log p(x) is the gradient of the log-density with respect to the data. It points toward higher-density regions. Diffusion models learn to estimate the score at various noise levels: given noisy data x_t, predict the direction toward clean data. Score matching trains a neural network to approximate s(x) without knowing the normalization constant of p(x), which is typically intractable. The reverse diffusion process follows the estimated score to generate samples', 'Score functions require knowing the normalization constant of the distribution', 'Diffusion models do not use score functions'], correctAnswer: 1, explanation: 'Score function s(x) = ∇_x log p(x) tells you: "from point x, which direction increases the data probability?" In diffusion: (1) forward process adds noise: x_t = √ᾱ_t x_0 + √(1-ᾱ_t) ε, (2) the score of the noisy distribution: s_θ(x_t, t) ≈ ∇_{x_t} log p_t(x_t), (3) the trained network actually predicts ε (the noise), and the score is s = -ε/√(1-ᾱ_t). (4) Reverse sampling follows the estimated score: x_{t-1} = f(x_t, s_θ(x_t, t)). Score matching loss: ||s_θ(x) - ∇_x log p(x)||² — but ∇_x log p(x) is unknown. Denoising score matching: train s_θ to denoise: ||s_θ(x̃) - ∇_x̃ log p(x̃|x)||², where p(x̃|x) = N(x, σ²) has known score. This is equivalent and tractable.', tags: ['score-function', 'diffusion', 'score-matching', 'denoising'] },
  { id: 'ai-engineer-math-stats-l4-024', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Statistics', question: 'What is the difference between parametric and non-parametric statistical tests for comparing ML models?', options: ['Parametric and non-parametric tests give identical results', 'Non-parametric tests require larger sample sizes than parametric tests', 'Parametric tests always have more statistical power', 'Parametric tests (paired t-test) assume the performance differences are normally distributed and use mean/variance. Non-parametric tests (Wilcoxon signed-rank, permutation test) make no distributional assumptions and use ranks or resampling. For ML: when comparing model accuracies across K folds, the normality assumption may not hold (especially with small K). Non-parametric tests are more robust but less powerful. Permutation tests are increasingly preferred as they are assumption-free and easy to implement'], correctAnswer: 3, explanation: 'Comparing model A vs B across 10 CV folds: Paired t-test: d_i = acc_A_i - acc_B_i, test H0: mean(d) = 0. Assumes d_i ~ Normal. Valid with large samples (CLT) or truly normal differences. Wilcoxon signed-rank: ranks |d_i|, sums positive and negative ranks separately. No normality assumption, but less powerful. Permutation test: randomly reassign A/B labels 10000 times, compute test statistic, p-value = fraction of permutations with larger statistic. No assumptions, exact type I error control. For ML specifically: (1) 10-fold CV violates independence (overlapping training sets), so Nadeau & Bengio corrected t-test adjusts variance, (2) McNemar\'s test compares models on individual predictions (not aggregate accuracy), (3) bootstrap comparison provides CI of performance difference.', tags: ['parametric', 'non-parametric', 'hypothesis-testing', 'model-comparison'] },
  { id: 'ai-engineer-math-stats-l4-025', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Information Theory', question: 'What is the Information Bottleneck principle and how does it relate to deep learning representations?', options: ['The Information Bottleneck principle states that optimal representations Z of input X for predicting Y should maximize I(Z;Y) (relevant information) while minimizing I(Z;X) (compression). This trades off prediction quality against representation complexity. Tishby\'s deep learning theory suggests neural network layers progressively compress input information while preserving task-relevant information, though this claim remains debated for networks with non-saturating activations like ReLU', 'The Information Bottleneck has been proven irrelevant to deep learning', 'The Information Bottleneck is about data compression only', 'I(Z;X) should always be maximized, not minimized'], correctAnswer: 0, explanation: 'IB objective: min_{p(z|x)} I(Z;X) - β·I(Z;Y). β controls the trade-off: β→∞ prioritizes prediction (keep all info about Y), β→0 prioritizes compression (minimize info about X). Tishby & Shwartz-Ziv (2017) argued that DNN training has two phases: (1) fitting phase: both I(Z;X) and I(Z;Y) increase, (2) compression phase: I(Z;X) decreases while I(Z;Y) stays high — the network "forgets" irrelevant input details. Controversy: Saxe et al. (2018) showed compression only occurs with saturating activations (sigmoid/tanh), not ReLU. Despite the debate, the IB framework provides useful intuition: good representations capture task-relevant features while discarding noise, and regularization techniques (dropout, weight decay) encourage this compression.', tags: ['information-bottleneck', 'mutual-information', 'representation-learning', 'compression'] },
  { id: 'ai-engineer-math-stats-l4-026', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'What is the role of orthogonal initialization in deep neural networks?', options: ['Orthogonal matrices always have determinant zero', 'Orthogonal initialization sets weight matrices as random orthogonal matrices (Q^TQ = I). This preserves the norm of signals during forward and backward passes because ||Qx|| = ||x|| for orthogonal Q. This prevents both vanishing and exploding gradients in deep networks, maintaining signal magnitude across many layers. It is particularly important for RNNs where the same weight matrix is applied repeatedly across time steps', 'Orthogonal initialization sets all weights to zero', 'Orthogonal initialization is only used for the first layer'], correctAnswer: 1, explanation: 'For a linear network y = W_L...W_2·W_1·x: if each W_i is orthogonal, ||y|| = ||x|| regardless of depth L (orthogonal matrices preserve norms). For nonlinear networks: orthogonal init combined with appropriate nonlinearity scaling (Saxe et al. 2014) achieves "dynamical isometry" — both forward signals and backward gradients maintain constant magnitude across layers. This enables training very deep networks (100+ layers) without batch normalization. For RNNs: h_t = σ(W_h·h_{t-1} + W_x·x_t). W_h applied T times → eigenvalues determine gradient flow. Orthogonal W_h has all eigenvalues with magnitude 1, preventing vanishing/exploding gradients across T timesteps. PyTorch: nn.init.orthogonal_(layer.weight).', tags: ['orthogonal-initialization', 'gradient-flow', 'dynamical-isometry', 'rnn'] },
  { id: 'ai-engineer-math-stats-l4-027', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What are Lipschitz constraints and why are they important for stable GAN training and robustness?', options: ['Lipschitz constraints always improve model accuracy', 'Lipschitz constraints only apply to linear functions', 'A function f is K-Lipschitz if ||f(x)-f(y)|| ≤ K·||x-y|| for all x,y — the function\'s output cannot change faster than K times its input change. In GANs: the Wasserstein GAN requires a 1-Lipschitz discriminator for meaningful gradients. Enforced via weight clipping, gradient penalty, or spectral normalization. For robustness: a K-Lipschitz classifier cannot change its output much for small input perturbations, providing certified adversarial robustness with radius 1/(2K)', 'Only linear functions can be Lipschitz continuous'], correctAnswer: 2, explanation: 'Lipschitz constant K = max_x ||∇f(x)||: the maximum gradient norm. Spectral normalization: normalize each weight matrix W by its spectral norm σ(W) (largest singular value), ensuring each layer is 1-Lipschitz. The overall network is then K=Π_i 1 = 1-Lipschitz. WGAN: critic must be 1-Lipschitz for the Wasserstein distance to be well-defined. Gradient penalty: add λ·(||∇_x D(x̂)|| - 1)² where x̂ is interpolated between real and fake. For adversarial robustness: if the classifier changes output by at most K·ε for any ε-perturbation, and the margin is > K·ε, the prediction is provably correct. Lipschitz networks (Anil et al. 2019) explicitly construct certifiably robust classifiers.', tags: ['lipschitz', 'spectral-normalization', 'wgan', 'robustness'] },
  { id: 'ai-engineer-math-stats-l4-028', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the difference between aleatoric and epistemic uncertainty in ML predictions?', options: ['More data always reduces both types of uncertainty', 'Aleatoric and epistemic uncertainty are the same thing', 'Aleatoric uncertainty is inherent data noise that cannot be reduced with more data (e.g., sensor noise, inherent randomness in outcomes). Epistemic uncertainty is model uncertainty due to limited training data, which decreases as more data is collected. Distinguishing them matters for decision-making: high aleatoric uncertainty suggests the task is fundamentally hard, while high epistemic uncertainty suggests collecting more data or using a different model could help', 'Only aleatoric uncertainty matters for production ML systems'], correctAnswer: 2, explanation: 'Aleatoric: two patients with identical features have different outcomes → inherent outcome variability. Captured by: model predicting a distribution (e.g., Gaussian output with learned variance), heteroscedastic regression. Cannot be reduced by more data — this is irreducible uncertainty. Epistemic: model hasn\'t seen data in a region of feature space → uncertain about predictions there. Captured by: Bayesian posterior variance, ensemble disagreement, MC Dropout variance. Reduces as training data increases. Practical: total uncertainty = aleatoric + epistemic. High epistemic: collect more data for that region. High aleatoric: accept the noise, don\'t expect better predictions. Kendall & Gal (2017) showed how to estimate both simultaneously in a single neural network.', tags: ['aleatoric', 'epistemic', 'uncertainty', 'heteroscedastic'] },
  { id: 'ai-engineer-math-stats-l4-029', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Statistics', question: 'What is the central limit theorem\'s relevance to mini-batch gradient estimation?', options: ['The CLT has no relevance to gradient estimation', 'The CLT guarantees that the mini-batch gradient (average of B per-sample gradients) approaches a Gaussian distribution as B increases, regardless of the individual gradient distribution. This means: (1) the standard error of the gradient estimate decreases as 1/√B, (2) the gradient estimate is unbiased, (3) Gaussian noise properties enable theoretical analysis of SGD convergence. However, gradient distributions in practice can be heavy-tailed, slowing CLT convergence and motivating gradient clipping', 'Mini-batch size has no effect on gradient estimation quality', 'The CLT requires gradients to be normally distributed'], correctAnswer: 1, explanation: 'Mini-batch gradient: g_B = (1/B)Σ_{i=1}^B ∇L(x_i). By CLT: g_B → N(E[∇L], Var(∇L)/B) as B→∞. Practical implications: (1) Unbiased: E[g_B] = true gradient (for any B), (2) Variance: Var(g_B) = σ²/B — doubling batch size halves variance, (3) The Gaussian approximation enables theoretical convergence proofs. But: in practice, per-sample gradients can have heavy tails (outlier examples produce very large gradients), making CLT convergence slow and the Gaussian approximation poor for small B. Gradient clipping (clip per-sample gradient to max norm C) ensures bounded variance, restoring CLT applicability. Zhang et al. (2020) showed heavy-tailed gradients are common in transformer training, motivating per-sample clipping.', tags: ['clt', 'gradient-estimation', 'mini-batch', 'convergence'] },
  { id: 'ai-engineer-math-stats-l4-030', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Linear Algebra', question: 'What is the connection between attention mechanisms and kernel methods?', options: ['The kernel perspective only applies to self-attention, not cross-attention', 'Softmax attention can be viewed as a kernel function: A(Q,K) = softmax(QK^T/√d) resembles a normalized kernel matrix where K(q,k) = exp(q^Tk/√d). Linear attention replaces this with an explicit kernel: A(Q,K) = φ(Q)φ(K)^T for some feature map φ. This connection enables: (1) using kernel approximation theory to analyze attention, (2) random feature approximations of attention for linear complexity, (3) understanding attention as a non-parametric regression in feature space', 'Attention and kernel methods are completely unrelated', 'Kernel methods cannot achieve attention-like behavior'], correctAnswer: 1, explanation: 'Softmax attention: α_ij = exp(q_i^Tk_j/√d) / Σ_l exp(q_i^Tk_l/√d). This is a softmax kernel: K(q,k) = exp(q^Tk/√d), normalized across keys. The attention output v_i = Σ_j α_ij v_j is a kernel-weighted average — equivalent to Nadaraya-Watson kernel regression with the softmax kernel. Linear attention: replace softmax with φ(q)^Tφ(k) for feature map φ. Then: Attn(Q,K,V) = (φ(Q)φ(K)^T)V = φ(Q)(φ(K)^TV). The key insight: compute φ(K)^TV ∈ R^{d\'×d} first (O(N·d·d\')), then multiply by φ(Q) (O(N·d·d\')). Total: O(N·d·d\') vs O(N²·d) for standard attention. Performer uses random Fourier features to approximate the softmax kernel.', tags: ['attention-kernel', 'kernel-methods', 'linear-attention', 'performer'] },
  { id: 'ai-engineer-math-stats-l4-031', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is natural gradient descent and why does it converge faster than standard gradient descent?', options: ['Natural gradient only works for linear models', 'Natural gradient is identical to standard gradient descent with larger learning rate', 'Natural gradient always requires computing the full Hessian', 'Natural gradient descent adjusts the gradient by the inverse Fisher information matrix: θ -= lr · F⁻¹ · ∇L. While standard gradient descent moves in the steepest direction in parameter space, natural gradient moves in the steepest direction in distribution space (KL divergence). This accounts for the geometry of the parameter space — a small parameter change can cause a large distribution change in some directions but not others. F⁻¹ corrects for this curvature, achieving faster convergence'], correctAnswer: 3, explanation: 'Standard GD: moves in direction of steepest descent in Euclidean parameter space. Problem: if changing θ₁ by 0.01 changes the output distribution a lot, but changing θ₂ by 0.01 changes it very little, GD treats both equally. Natural GD: moves in direction of steepest descent in the space of distributions (measured by KL divergence). The Fisher information F = E[∇log p · (∇log p)^T] measures how much the distribution changes per parameter change. F⁻¹·∇L rescales the gradient so each parameter is updated proportionally to its distributional impact. Connection to Adam: Adam approximates diagonal F⁻¹ via the second moment estimate. KFAC approximates F⁻¹ using Kronecker factorization for efficiency. Practical speedup: 2-10x faster convergence for deep networks.', tags: ['natural-gradient', 'fisher-information', 'kfac', 'riemannian'] },
  { id: 'ai-engineer-math-stats-l4-032', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Probability', question: 'What is the PAC (Probably Approximately Correct) learning framework and what does it guarantee?', options: ['PAC learning guarantees perfect accuracy on any dataset', 'PAC learning provides theoretical guarantees: a learning algorithm is PAC if, for any desired accuracy ε and confidence δ, there exists a sample size N such that with probability at least 1-δ, the learned hypothesis has error at most ε. The required N depends on the hypothesis class complexity (VC dimension). This provides a theoretical foundation for understanding how much data is needed to learn reliably, though the bounds are often too loose to be practically useful for deep learning', 'PAC bounds are tight enough to determine exact sample sizes for deep learning', 'PAC learning only applies to binary classification'], correctAnswer: 1, explanation: 'PAC guarantee: P(error(h) ≤ ε) ≥ 1-δ when trained on N ≥ O((d·log(1/ε) + log(1/δ))/ε) samples, where d is the VC dimension of the hypothesis class. For finite hypothesis classes: N ≥ (1/ε)(log|H| + log(1/δ)). The VC dimension d measures the maximum number of points that can be shattered (assigned arbitrary labels) by the hypothesis class. Linear classifiers in R^n: d = n+1. Neural networks: VC dimension scales with number of parameters, but the bounds are extremely loose. Despite loose bounds, PAC theory provides: (1) understanding that more complex models need more data, (2) the concept of sample complexity, (3) the basis for regularization theory (restrict hypothesis class complexity to improve generalization).', tags: ['pac-learning', 'vc-dimension', 'sample-complexity', 'learning-theory'] },
  { id: 'ai-engineer-math-stats-l4-033', language: 'ai-engineer', level: 'level4', category: 'Math & Statistics', subcategory: 'Optimization', question: 'What is the Lottery Ticket Hypothesis from a mathematical perspective?', options: ['All random subnetworks perform equally well', 'The Lottery Ticket Hypothesis is about random data sampling', 'The hypothesis has been mathematically disproven', 'The Lottery Ticket Hypothesis states that dense networks contain sparse subnetworks (winning tickets) that, when trained from their original initialization, achieve comparable accuracy to the full network. Mathematically: there exists a mask m ∈ {0,1}^N and initialization θ_0 such that training f(x; m⊙θ_0) achieves similar loss to training f(x; θ_0) with the full parameter set. This suggests the initialization encodes important structure, and the training process primarily identifies which connections matter'], correctAnswer: 3, explanation: 'The hypothesis (Frankle & Carlin 2019): Dense network with parameters θ_0 → train → get θ_T → prune (keep top-k% by magnitude) → get mask m → reset weights to θ_0 → retrain m⊙θ_0 → achieves similar accuracy at k=10-20% sparsity. Mathematical implications: (1) the landscape of the subnetwork f(x; m⊙θ) at initialization θ_0 is already "good" — the subnetwork can reach a good minimum, (2) the initialization matters (random re-initialization fails), (3) this connects to the over-parameterization theory — large networks are easier to train because they contain more "winning tickets." Strong Lottery Ticket (Ramanujan et al. 2020): for sufficiently over-parameterized random networks, good subnetworks exist WITHOUT any training — just finding the right mask is sufficient.', tags: ['lottery-ticket', 'sparsity', 'initialization', 'pruning-theory'] },
];

export default questions;
